/* Demonstrates sscanf() extracting typed data (string and integer) from a predefined string. */
#include <stdio.h>
#include <string.h>

int main() {
    const char *input_data = "Item ID: 500, Price: 19.99 USD";
    int item_id;
    float price;
    char currency[5];
    int assignments;

    // Format string extracts the ID (integer), the Price (float), and the currency (string).
    // We expect 3 successful assignments.
    assignments = sscanf(input_data, "Item ID: %d, Price: %f %s", 
                         &item_id, &price, currency);

    if (assignments == 3) {
        printf("Parsing successful. %d items assigned.\n", assignments);
        printf("ID: %d\n", item_id);
        printf("Price: %.2f\n", price);
        printf("Currency: %s\n", currency);
    } else if (assignments == EOF) {
        fprintf(stderr, "Error: Input string was empty or reached EOF immediately.\n");
        return 1;
    } else {
        fprintf(stderr, "Parsing failed. Expected 3 assignments, got %d.\n", assignments);
        // We can inspect item_id and price here, as they might have been assigned before the failure.
        return 1;
    }

    // Example of failure due to data mismatch:
    const char *bad_data = "Item ID: XYZ, Price: 10.00";
    int temp_id;
    assignments = sscanf(bad_data, "Item ID: %d", &temp_id);
    printf("\nAttempting bad data parsing:\n");
    printf("Resulting assignments: %d\n", assignments);

    return 0;
}
